#include <stdlib.h>
#include <string.h>
#include <omp.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 96
#define NB 192

typedef float v8 __attribute__((vector_size(32), aligned(32)));
typedef float v8u __attribute__((vector_size(32), aligned(4)));

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int mr, int nr, int acc)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int p = 0; p < kc; p++) {
        const v8 b0 = *(const v8 *)(b);
        const v8 b1 = *(const v8 *)(b + 8);
        float a0 = a[0], a1 = a[1], a2 = a[2], a3 = a[3], a4 = a[4], a5 = a[5];
        c00 += b0 * a0; c01 += b1 * a0;
        c10 += b0 * a1; c11 += b1 * a1;
        c20 += b0 * a2; c21 += b1 * a2;
        c30 += b0 * a3; c31 += b1 * a3;
        c40 += b0 * a4; c41 += b1 * a4;
        c50 += b0 * a5; c51 += b1 * a5;
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
#define ST(r, x0, x1)                                              \
        {                                                          \
            v8u *p0 = (v8u *)(c + (r) * ldc);                      \
            v8u *p1 = (v8u *)(c + (r) * ldc + 8);                  \
            if (acc) { *p0 += x0; *p1 += x1; }                     \
            else { *p0 = x0; *p1 = x1; }                           \
        }
        ST(0, c00, c01) ST(1, c10, c11) ST(2, c20, c21)
        ST(3, c30, c31) ST(4, c40, c41) ST(5, c50, c51)
#undef ST
    } else {
        float t[MR * NR] __attribute__((aligned(32)));
        *(v8 *)(t + 0 * NR) = c00; *(v8 *)(t + 0 * NR + 8) = c01;
        *(v8 *)(t + 1 * NR) = c10; *(v8 *)(t + 1 * NR + 8) = c11;
        *(v8 *)(t + 2 * NR) = c20; *(v8 *)(t + 2 * NR + 8) = c21;
        *(v8 *)(t + 3 * NR) = c30; *(v8 *)(t + 3 * NR + 8) = c31;
        *(v8 *)(t + 4 * NR) = c40; *(v8 *)(t + 4 * NR + 8) = c41;
        *(v8 *)(t + 5 * NR) = c50; *(v8 *)(t + 5 * NR + 8) = c51;
        for (int i = 0; i < mr; i++)
            for (int j = 0; j < nr; j++) {
                if (acc) c[i * ldc + j] += t[i * NR + j];
                else c[i * ldc + j] = t[i * NR + j];
            }
    }
}

static void pack_A(const float *A, int n, int i0, int mc, int k0, int kc, float *buf)
{
    for (int ir = 0; ir < mc; ir += MR) {
        int m = mc - ir < MR ? mc - ir : MR;
        const float *src = A + (size_t)(i0 + ir) * n + k0;
        float *dst = buf + (size_t)ir * kc;
        if (m == MR) {
            for (int p = 0; p < kc; p++)
                for (int r = 0; r < MR; r++)
                    dst[p * MR + r] = src[(size_t)r * n + p];
        } else {
            for (int p = 0; p < kc; p++)
                for (int r = 0; r < MR; r++)
                    dst[p * MR + r] = r < m ? src[(size_t)r * n + p] : 0.0f;
        }
    }
}

static void pack_B_panel(const float *B, int n, int k0, int kc, int j0, float *dst)
{
    int w = n - j0 < NR ? n - j0 : NR;
    const float *src = B + (size_t)k0 * n + j0;
    if (w == NR) {
        for (int p = 0; p < kc; p++)
            memcpy(dst + p * NR, src + (size_t)p * n, NR * sizeof(float));
    } else {
        for (int p = 0; p < kc; p++)
            for (int c = 0; c < NR; c++)
                dst[p * NR + c] = c < w ? src[(size_t)p * n + c] : 0.0f;
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int npan = (n + NR - 1) / NR;
    size_t bsz = (size_t)npan * NR * KC * sizeof(float);
    float *Bp = (float *)aligned_alloc(64, (bsz + 63) & ~(size_t)63);

    int nib = (n + MC - 1) / MC;
    int njb = (n + NB - 1) / NB;
    int ntasks = nib * njb;

#pragma omp parallel if (n > 96)
    {
        size_t asz = (size_t)MC * KC * sizeof(float);
        float *Ap = (float *)aligned_alloc(64, (asz + 63) & ~(size_t)63);

        for (int k0 = 0; k0 < n; k0 += KC) {
            int kc = n - k0 < KC ? n - k0 : KC;
            int acc = k0 > 0;

#pragma omp for schedule(static)
            for (int jp = 0; jp < npan; jp++)
                pack_B_panel(B, n, k0, kc, jp * NR, Bp + (size_t)jp * NR * kc);

#pragma omp for schedule(dynamic, 1)
            for (int t = 0; t < ntasks; t++) {
                int ib = t / njb, jb = t % njb;
                int i0 = ib * MC;
                int mc = n - i0 < MC ? n - i0 : MC;
                int j0 = jb * NB;
                int jend = j0 + NB < n ? j0 + NB : n;
                pack_A(A, n, i0, mc, k0, kc, Ap);
                for (int j = j0; j < jend; j += NR) {
                    int nr = jend - j < NR ? jend - j : NR;
                    const float *bp = Bp + (size_t)(j / NR) * NR * kc;
                    for (int ir = 0; ir < mc; ir += MR) {
                        int mr = mc - ir < MR ? mc - ir : MR;
                        kernel(kc, Ap + (size_t)ir * kc, bp,
                               C + (size_t)(i0 + ir) * n + j, n, mr, nr, acc);
                    }
                }
            }
        }
        free(Ap);
    }
    free(Bp);
}
